#include <iostream>
#include <string>

// Represents the interface that would normally be placed in GradeBook.h
class GradeBook {
public:
    explicit GradeBook(std::string name);
    void setCourseName(std::string name);
    std::string getCourseName() const;
    void displayMessage() const;
private:
    std::string courseName;
};

// Represents the implementation that would reside in GradeBook.cpp
// Demonstrates proper usage of ClassName:: operator
GradeBook::GradeBook(std::string name) {
    courseName = name;
}

void GradeBook::setCourseName(std::string name) {
    courseName = name;
}

std::string GradeBook::getCourseName() const {
    return courseName;
}

void GradeBook::displayMessage() const {
    std::cout << "Welcome to the grade book for: " << getCourseName() << "!\n";
}

// Represents the client code that would reside in main.cpp
int main() {
    GradeBook gradeBook1("CS101 Introduction to C++ Programming");
    GradeBook gradeBook2("CS102 Data Structures in C++");

    std::cout << "gradeBook1 created for course: " << gradeBook1.getCourseName() << '\n';
    std::cout << "gradeBook2 created for course: " << gradeBook2.getCourseName() << '\n';

    return 0;
}

#include <iostream>
#include <string>

class GradeBook {
public:
    // Constructor validates input by delegating to setCourseName
    explicit GradeBook(std::string name) {
        setCourseName(name);
    }

    // Validates that courseName does not exceed 25 characters
    void setCourseName(std::string name) {
        if (name.size() <= 25) {
            courseName = name;
        } else {
            // Truncate to first 25 characters if constraint is violated
            courseName = name.substr(0, 25);
            std::cout << "Name \"" << name << "\" exceeds maximum length (25).\n"
                      << "Limiting courseName to first 25 characters.\n\n";
        }
    }

    std::string getCourseName() const {
        return courseName;
    }

    void displayMessage() const {
        std::cout << "Course name: " << courseName << "\n";
    }

private:
    std::string courseName;
};

int main() {
    // Valid length (<= 25 chars)
    GradeBook gradeBook1("CS101 C++ Programming");

    // Invalid length (> 25 chars)
    GradeBook gradeBook2("CS102 Advanced Data Structures and Algorithms");

    std::cout << "gradeBook1's course name is: " << gradeBook1.getCourseName() << "\n";
    std::cout << "gradeBook2's course name is: " << gradeBook2.getCourseName() << "\n";

    return 0;
}
